//! TypeScript client generation from the Application Contract
//! (slice 51l).
//!
//! Two thin generated files are produced per app:
//!
//! - `types.ts` — one `interface` per record type and one discriminated
//!   union per sum/error type, so a frontend gets exhaustive, typed
//!   handling of every value the surface exchanges (including the
//!   `@status`/`@ui` error metadata from slice 51e).
//! - `api.ts` — a typed method per public agent/prompt, a `route()`
//!   call for each route that returns a stream (keyed by its method and
//!   path), plus the auth helpers derived from the `identity` block. Each
//!   method is a one-liner that delegates to the generic
//!   `@corvid/client` transport — the HTTP/SSE/session/error behavior
//!   lives in that shipped package and is REUSED, never regenerated
//!   per app. That is what keeps the generated code small and the
//!   moat (streaming events, approvals, grounding, pagination) in one
//!   audited place.

use crate::app_contract::{ApplicationContract, ContractType};

/// A generated source file: a repo-relative-ish filename plus its
/// contents. The CLI writes each into the chosen output directory.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GeneratedFile {
    pub filename: String,
    pub contents: String,
}

/// Generate the `types.ts` + `api.ts` pair for a contract.
pub fn emit_ts_client(contract: &ApplicationContract) -> Vec<GeneratedFile> {
    vec![
        GeneratedFile {
            filename: "types.ts".to_string(),
            contents: emit_types(contract),
        },
        GeneratedFile {
            filename: "api.ts".to_string(),
            contents: emit_api(contract),
        },
    ]
}

const GENERATED_HEADER: &str = "// Generated by `corvid contract ts-client` — do not edit by hand.\n// Regenerate whenever the Corvid source changes; the transport and\n// behavior live in `@corvid/client` and are reused, not regenerated.\n";

fn emit_types(contract: &ApplicationContract) -> String {
    let mut out = String::new();
    out.push_str(GENERATED_HEADER);
    out.push('\n');
    for ty in &contract.types {
        out.push_str(&type_declaration(ty));
        out.push('\n');
    }
    out.push_str(&emit_protocol_types(contract));
    out
}

/// Project every declared provider protocol into TypeScript.
///
/// A long-running operation does not return a value, it returns a
/// *lifecycle*, and a client that models it as a nullable result loses
/// the two facts that matter: which states are terminal, and that one of
/// the terminal states is reached by the provider simply being slow. The
/// emitted state union is discriminated on `terminal`, so a `switch` that
/// forgets the deadline outcome fails to compile rather than falling
/// through at runtime.
///
/// The protocol fingerprint is emitted alongside, so a client can tell
/// whether the backend is still running the protocol these types were
/// generated from.
fn emit_protocol_types(contract: &ApplicationContract) -> String {
    let mut out = String::new();
    for connector in &contract.connectors {
        for operation in &connector.operations {
            let Some(protocol) = &operation.protocol else {
                continue;
            };
            let base = format!(
                "{}{}",
                upper_first(&connector.name),
                upper_camel(&operation.name)
            );

            out.push_str(&format!(
                "/** Statuses `{}.{}` may report. Any other status is refused at the\n \
                 * typed boundary rather than coerced. */\n",
                connector.name, operation.name
            ));
            out.push_str(&format!(
                "export type {base}Status =\n{};\n\n",
                protocol
                    .statuses
                    .iter()
                    .map(|s| format!("  | {}", quote(s)))
                    .collect::<Vec<_>>()
                    .join("\n")
            ));

            out.push_str(&format!(
                "/** States an in-flight `{}.{}` intent can be observed in.\n \
                 * Discriminated on `terminal` so an exhaustive `switch` cannot\n \
                 * silently omit an outcome — including `{}`, which is reached\n \
                 * when the provider is merely slow. */\n",
                connector.name, operation.name, protocol.deadline_target
            ));
            let terminal: std::collections::BTreeSet<&str> =
                protocol.terminal.iter().map(|t| t.as_str()).collect();
            let mut states: Vec<&str> = protocol.states.iter().map(|s| s.name.as_str()).collect();
            for t in &protocol.terminal {
                if !states.contains(&t.as_str()) {
                    states.push(t.as_str());
                }
            }
            out.push_str(&format!(
                "export type {base}State =\n{};\n\n",
                states
                    .iter()
                    .map(|state| format!(
                        "  | {{ state: {}; terminal: {} }}",
                        quote(state),
                        terminal.contains(state)
                    ))
                    .collect::<Vec<_>>()
                    .join("\n")
            ));

            out.push_str(&format!(
                "/** The declared protocol, as the backend compiled it. */\n\
                 export const {base}Protocol = {{\n  \
                 fingerprint: {},\n  \
                 initial: {},\n  \
                 terminal: [{}] as const,\n  \
                 deadlineSeconds: {},\n  \
                 deadlineTarget: {},\n  \
                 pollSeconds: {},\n  \
                 onProtocolChange: {},\n\
                 }} as const;\n\n",
                quote(&protocol.fingerprint),
                quote(&protocol.initial),
                protocol
                    .terminal
                    .iter()
                    .map(|t| quote(t))
                    .collect::<Vec<_>>()
                    .join(", "),
                protocol.deadline_secs,
                quote(&protocol.deadline_target),
                protocol
                    .interval
                    .seconds
                    .map(|s| s.to_string())
                    .unwrap_or_else(|| "null".to_string()),
                quote(&protocol.on_protocol_change),
            ));
        }
    }
    out
}

/// A record property name: bare when it is a plain identifier, quoted
/// otherwise.
fn ts_property(key: &str) -> String {
    let mut chars = key.chars();
    let plain = chars.next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_' || c == '$')
        && chars.all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$');
    if plain { key.to_string() } else { quote(key) }
}

fn quote(value: &str) -> String {
    serde_json::to_string(value).expect("a string is a JSON literal")
}

fn upper_first(name: &str) -> String {
    let mut chars = name.chars();
    match chars.next() {
        Some(c) => c.to_uppercase().collect::<String>() + chars.as_str(),
        None => String::new(),
    }
}

/// `submit_shipment` -> `SubmitShipment`.
fn upper_camel(name: &str) -> String {
    name.split('_').map(upper_first).collect()
}

fn type_declaration(ty: &ContractType) -> String {
    if !ty.variants.is_empty() {
        return sum_type_declaration(ty);
    }
    let mut out = format!("export interface {} {{\n", ty.name);
    for f in &ty.fields {
        let optional = if f.type_name.starts_with("Option<") { "?" } else { "" };
        // A field with an upload surface is a File/Blob on the wire.
        let ts = if f.upload.is_some() {
            "File".to_string()
        } else {
            ts_type(&f.type_name)
        };
        // The property is the wire key (`@json(key:)`, B01), quoted when
        // it is not a plain identifier, such as `created-at`.
        out.push_str(&format!("  {}{}: {};\n", ts_property(f.key()), optional, ts));
    }
    out.push_str("}\n");
    out
}

/// A sum type projects to a union discriminated by `variant`, matching
/// the public JSON mapping: `{"tag": "variant", "type": …, "variant": …,
/// "fields": [...]}` with payload fields in declaration order. Error
/// variants keep their `@status` / `@ui` metadata on a companion
/// const map so a frontend renders a default per branch.
fn sum_type_declaration(ty: &ContractType) -> String {
    let mut out = String::new();
    let arms: Vec<String> = ty
        .variants
        .iter()
        .map(|v| {
            let mut arm = format!(
                "{{ tag?: \"variant\"; type?: \"{}\"; variant: \"{}\"",
                ty.name, v.name
            );
            if !v.fields.is_empty() {
                let fields = v
                    .fields
                    .iter()
                    .map(|f| format!("{}: {}", f.name, ts_type(&f.type_name)))
                    .collect::<Vec<_>>()
                    .join(", ");
                arm.push_str(&format!("; fields: [{fields}]"));
            }
            arm.push_str(" }");
            arm
        })
        .collect();
    out.push_str(&format!("export type {} =\n  | {};\n", ty.name, arms.join("\n  | ")));

    // Presentation/status metadata map, when any variant carries it.
    let has_meta = ty
        .variants
        .iter()
        .any(|v| v.status.is_some() || !v.ui.is_empty());
    if has_meta {
        out.push_str(&format!(
            "\nexport const {}Meta: Record<string, {{ status?: number; ui?: Record<string, unknown> }}> = {{\n",
            ty.name
        ));
        for v in &ty.variants {
            if v.status.is_none() && v.ui.is_empty() {
                continue;
            }
            let status = v
                .status
                .map(|s| format!("status: {s}"))
                .unwrap_or_default();
            let ui = if v.ui.is_empty() {
                String::new()
            } else {
                let ui_json = serde_json::to_string(&v.ui).unwrap_or_else(|_| "{}".to_string());
                format!("ui: {ui_json}")
            };
            let body = [status, ui]
                .into_iter()
                .filter(|s| !s.is_empty())
                .collect::<Vec<_>>()
                .join(", ");
            out.push_str(&format!("  {}: {{ {} }},\n", v.name, body));
        }
        out.push_str("};\n");
    }
    out
}

fn emit_api(contract: &ApplicationContract) -> String {
    let mut out = String::new();
    out.push_str(GENERATED_HEADER);
    out.push('\n');
    if !contract.live.is_empty() {
        out.push_str("import { fillPath } from \"@corvid/client\";\n");
    }
    let pending = if contract.actions.iter().any(|a| a.approval.is_some()) { " type ApprovalPending," } else { "" };
    out.push_str(&format!(
        "import {{ CorvidClient,{pending} type Page, type RouteShape, type RouteStream }} from \"@corvid/client\";\n",
    ));
    // Import every generated type so method signatures resolve.
    if !contract.types.is_empty() {
        let names: Vec<&str> = contract.types.iter().map(|t| t.name.as_str()).collect();
        out.push_str(&format!("import type {{ {} }} from \"./types\";\n", names.join(", ")));
    }
    out.push('\n');
    let routes = stream_routes(contract);
    out.push_str(&routes.tables);
    out.push_str("export class Api {\n");
    out.push_str("  constructor(private readonly client: CorvidClient) {}\n\n");
    if !contract.live.is_empty() {
        out.push_str(&live_methods(contract));
    }
    out.push_str(&routes.method);

    // A client calls the backend through its declared actions. Public
    // agents and prompts get no method: no server answers a call to one,
    // and serving one would open what no source declared callable.
    for action in &contract.actions {
        out.push_str(&action_method(action));
    }

    // Auth helpers from the identity block (slice 51h).
    for identity in &contract.identities {
        for provider in &identity.providers {
            out.push_str(&format!(
                "  loginWith_{p}(): void {{ this.client.login(\"{p}\"); }}\n",
                p = sanitize_ident(&provider.name)
            ));
        }
        out.push_str("  session(): Promise<unknown> { return this.client.session(); }\n");
        out.push_str("  logout(): Promise<void> { return this.client.logout(); }\n");
    }

    out.push_str("}\n");
    out
}

fn live_methods(contract: &ApplicationContract) -> String {
    let mut servers = std::collections::BTreeMap::new();
    for live in &contract.live {
        servers.entry(&live.server).or_insert_with(Vec::new).push(live);
    }
    let mut group = "live".to_owned();
    while contract.actions.iter().any(|a| a.callable.name == group) {
        group.push('_');
    }
    let mut out = format!("  readonly {group} = {{\n");
    for (server, declarations) in servers {
        out.push_str(&format!("    [{}]: {{\n", quote(server)));
        for live in declarations {
            let row = &live.row_type;
            let mut params = Vec::new();
            let mut arguments = Vec::new();
            for param in &live.path_params {
                // Prefix source identifiers so reserved JS names and 'observer'
                // remain valid arguments. Each value fills one encoded segment.
                let arg = format!("path_{}", param.name);
                params.push(format!("{arg}: {}", ts_type(&param.type_name)));
                arguments.push(format!("[{}]: {arg}", quote(&param.name)));
            }
            let path = format!("fillPath({}, {{ {} }})", quote(&live.path), arguments.join(", "));
            params.push(format!("observer: import(\"@corvid/client\").LiveObserver<{row}>"));
            let keys = serde_json::to_string(&live.key_fields).expect("string key names");
            out.push_str(&format!(
                "      [{}]: ({}): (() => void) =>\n        this.client.subscribe<{row}>({path}, {keys}, observer),\n",
                quote(&live.name), params.join(", ")
            ));
        }
        out.push_str("    },\n");
    }
    out.push_str("  };\n\n");
    out
}

/// The generated code for calling the app's streaming routes: the
/// `Routes` table and its runtime shapes, emitted before `Api`, and the
/// `route` method inside it.
struct StreamRoutes {
    tables: String,
    method: String,
}

/// Every route that returns `Stream<Item>`, keyed by its method and
/// contract path (`"GET /boards/{board}/feed"`), so a call names the route
/// as the source declares it and a changed path or parameter type fails to
/// compile at every caller. Arguments are the path parameters in path
/// order, then the query record, then the body.
///
/// Only streaming routes are generated so far; ordinary routes join the
/// same table next (frontend roadmap). A streaming route with an `Upload`
/// body is left out and named in a comment, because the client cannot yet
/// send multipart. A verified route is never generated: it is a
/// provider's signed call, which no browser can make.
fn stream_routes(contract: &ApplicationContract) -> StreamRoutes {
    let mut entries = Vec::new();
    let mut example = None;
    let mut shapes = Vec::new();
    let mut skipped = Vec::new();
    for route in contract.routes.iter().filter(|route| route.verified.is_none()) {
        let Some(item) = route
            .pagination
            .as_ref()
            .filter(|p| p.style == crate::app_contract::PaginationStyle::Stream)
            .map(|p| &p.item_type)
        else {
            continue;
        };
        let key = quote(&format!("{} {}", route.method, route.path));
        if route.upload.is_some() {
            skipped.push(key);
            continue;
        }
        let mut args: Vec<String> = route
            .path_params
            .iter()
            .map(|param| format!("{}: {}", sanitize_ident(&param.name), ts_type(&param.type_name)))
            .collect();
        if let Some(query) = &route.query_type {
            args.push(format!("query: {}", ts_type(query)));
        }
        let body = match (&route.body_type, route.request_media_type.as_deref()) {
            (None, _) => "null",
            (Some(body), Some("application/x-www-form-urlencoded")) => {
                args.push(format!("body: {}", ts_type(body)));
                "\"form\""
            }
            (Some(body), _) => {
                args.push(format!("body: {}", ts_type(body)));
                "\"json\""
            }
        };
        example.get_or_insert_with(|| {
            let mut call = vec![key.clone()];
            call.extend(route.path_params.iter().map(|param| sanitize_ident(&param.name)));
            call.join(", ")
        });
        entries.push(format!(
            "  {key}: {{ args: [{}]; reply: RouteStream<{}> }};\n",
            args.join(", "),
            ts_type(item)
        ));
        let params: Vec<String> = route.path_params.iter().map(|param| quote(&param.name)).collect();
        shapes.push(format!(
            "  {key}: {{ params: [{}], query: {}, body: {body} }},\n",
            params.join(", "),
            route.query_type.is_some()
        ));
    }
    let mut tables = String::new();
    for key in &skipped {
        tables.push_str(&format!(
            "// Not generated yet: {key} streams over an `Upload` body, which the client cannot send.\n"
        ));
    }
    if entries.is_empty() {
        if !skipped.is_empty() {
            tables.push('\n');
        }
        return StreamRoutes { tables, method: String::new() };
    }
    tables.push_str("/** The app's streaming routes, by method and path as declared. */\nexport interface Routes {\n");
    tables.extend(entries);
    tables.push_str("}\n\nconst ROUTES: { readonly [K in keyof Routes]: RouteShape } = {\n");
    tables.extend(shapes);
    tables.push_str("};\n\n");

    // `route` is a Corvid keyword, so no agent or prompt method can take
    // the name.
    let name = "route";
    let example = example.unwrap_or_default();
    let method = format!(
        "  /** Call a declared streaming route, as in `api.{name}({example})`. */\n  \
         {name}<K extends keyof Routes>(route: K, ...args: Routes[K][\"args\"]): Routes[K][\"reply\"] {{\n    \
         return this.client.routeStream(route, ROUTES[route], args) as Routes[K][\"reply\"];\n  }}\n\n"
    );
    StreamRoutes { tables, method }
}

/// An action's method, posting to `POST /actions/<name>` in the shape
/// the contract's `input_type` names: the record itself, or an object
/// with one field per parameter. An action with `@approval` can answer
/// with an `ApprovalPending`, and its return type says so, so a caller
/// that ignores the pending case does not compile.
fn action_method(action: &crate::app_contract::ContractAction) -> String {
    let c = &action.callable;
    let params: Vec<String> = c
        .inputs
        .iter()
        .map(|p| format!("{}: {}", sanitize_ident(&p.name), ts_type(&p.type_name)))
        .collect();
    let input = match (&action.input_type, c.inputs.first()) {
        (Some(_), Some(only)) => sanitize_ident(&only.name),
        _ => format!("{{ {} }}", c.inputs.iter().map(|p| sanitize_ident(&p.name)).collect::<Vec<_>>().join(", ")),
    };
    let name = sanitize_ident(&c.name);
    let params = params.join(", ");
    let orig = &c.name;
    if c.capabilities.streaming {
        // The server answers a streaming action with the route stream
        // protocol.
        let item = generic_inner(&c.output_type).unwrap_or_else(|| "unknown".to_string());
        return format!(
            "  /** Calls the `{orig}` action and reads its stream. */\n  {name}({params}): RouteStream<{item}> {{\n    return this.client.actionStream<{item}>(\"{orig}\", {input});\n  }}\n\n"
        );
    }
    let result = ts_type(&c.output_type);
    let ret = if action.approval.is_some() { format!("{result} | ApprovalPending") } else { result.clone() };
    let cast = if action.approval.is_some() { String::new() } else { format!(" as Promise<{result}>") };
    format!(
        "  /** Calls the `{orig}` action. */\n  {name}({params}): Promise<{ret}> {{\n    return this.client.action<{result}>(\"{orig}\", {input}){cast};\n  }}\n\n"
    )
}

/// Map a contract type name to a TypeScript type. Generic wrappers
/// unwrap to the shape a JSON client actually receives, mirroring the
/// OpenAPI projection.
fn ts_type(name: &str) -> String {
    match name {
        "Int" | "Float" => return "number".to_string(),
        "String" | "TraceId" => return "string".to_string(),
        // B06 — exact canonical text; JavaScript has no exact decimal
        // or nanosecond type, so a number or `Date` would lose data.
        name if corvid_public_json::text_scalar::is_name(name) => return "string".to_string(),
        "Bool" => return "boolean".to_string(),
        "Nothing" => return "null".to_string(),
        // The compiler-known `JsonError` record, written out inline.
        "JsonError" => {
            let fields: Vec<String> =
                corvid_types::json_error_fields().iter().map(|(field, _)| format!("{field}: string")).collect();
            return format!("{{ {} }}", fields.join("; "));
        }
        _ => {}
    }
    if let Some((head, inner)) = split_generic(name) {
        return match head {
            "List" => format!("{}[]", ts_type(inner)),
            "Option" => format!("{} | null", ts_type(inner)),
            "Stream" | "Tainted" => ts_type(inner),
            "Grounded" => format!(
                "{{ value: {}; sources: Array<{{ kind: string; name: string }}> }}",
                ts_type(inner)
            ),
            "Page" => format!("Page<{}>", ts_type(inner)),
            "Conflict" => conflict_union(&ts_type(inner)),
            "Upload" => "File".to_string(),
            "Result" => {
                let (ok, err) = inner.split_once(',').unwrap_or((inner, "string"));
                format!(
                    "{{ tag?: \"ok\"; ok: {} }} | {{ tag?: \"err\"; err: {} }}",
                    ts_type(ok.trim()),
                    ts_type(err.trim())
                )
            }
            "Map" => {
                let (_k, v) = inner.split_once(',').unwrap_or(("string", inner));
                format!("Record<string, {}>", ts_type(v.trim()))
            }
            // An unknown generic head keeps its name (a user type).
            _ => name.to_string(),
        };
    }
    // A bare named type is its generated interface/union.
    name.to_string()
}

/// A table write's conflict (B09) as the union its public JSON takes,
/// one arm per case, written the way a declared sum type is.
fn conflict_union(row: &str) -> String {
    corvid_types::ConflictCase::ALL
        .into_iter()
        .map(|case| match case.field() {
            Some(field) => format!(
                "{{ tag?: \"variant\"; type?: \"Conflict\"; variant: \"{}\"; fields: [{field}: {row}] }}",
                case.name()
            ),
            None => format!("{{ tag?: \"variant\"; type?: \"Conflict\"; variant: \"{}\" }}", case.name()),
        })
        .collect::<Vec<_>>()
        .join(" | ")
}

fn generic_inner(name: &str) -> Option<String> {
    split_generic(name).map(|(_, inner)| ts_type(inner))
}

fn split_generic(name: &str) -> Option<(&str, &str)> {
    let open = name.find('<')?;
    if !name.ends_with('>') {
        return None;
    }
    Some((&name[..open], &name[open + 1..name.len() - 1]))
}

/// Make an identifier safe for TS (the contract already uses valid
/// identifiers, but a defensive replace keeps generated code from ever
/// producing a syntax error on an odd provider alias).
fn sanitize_ident(name: &str) -> String {
    name.chars()
        .map(|c| if c.is_alphanumeric() || c == '_' { c } else { '_' })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn contract_for(src: &str) -> ApplicationContract {
        use crate::app_contract::{effect_decls_of, emit_application_contract, ContractOptions};
        use corvid_types::effects::EffectRegistry;
        let tokens = corvid_syntax::lex(src).expect("lex");
        let (file, perr) = corvid_syntax::parse_file(&tokens);
        assert!(perr.is_empty(), "parse: {perr:?}");
        let resolved = corvid_resolve::resolve(&file);
        assert!(resolved.errors.is_empty(), "resolve: {:?}", resolved.errors);
        let registry = EffectRegistry::from_decls(&effect_decls_of(&file));
        let checked = corvid_types::typecheck(&file, &resolved);
        assert!(checked.errors.is_empty(), "check: {:?}", checked.errors);
        emit_application_contract(
            &file,
            &resolved,
            &checked,
            &registry,
            &ContractOptions {
                source_path: "app.cor",
                compiler_version: "test",
                generated_at: "now",
            },
        )
    }

    #[test]
    fn record_and_error_types_project_to_interfaces_and_unions() {
        let contract = contract_for(
            "public type Answer:
    text: String
    score: Int

public type RefundError:
    @status(404)
    @ui(message: \"Not found.\")
    | PaymentNotFound
    | ApprovalDenied(reason: String)

public agent classify(q: String) -> Answer:
    return Answer(q, 1)
",
        );
        let files = emit_ts_client(&contract);
        let types = &files.iter().find(|f| f.filename == "types.ts").unwrap().contents;
        assert!(types.contains("export interface Answer {"));
        assert!(types.contains("text: string;"));
        assert!(types.contains("score: number;"));
        // Sum type → discriminated union + metadata map.
        assert!(types.contains("export type RefundError ="));
        assert!(types.contains(
            "{ tag?: \"variant\"; type?: \"RefundError\"; variant: \"PaymentNotFound\" }"
        ));
        assert!(types.contains(
            "{ tag?: \"variant\"; type?: \"RefundError\"; variant: \"ApprovalDenied\"; fields: [reason: string] }"
        ));
        assert!(types.contains("export const RefundErrorMeta"));
        assert!(types.contains("status: 404"));
    }

    #[test]
    fn agents_project_to_typed_methods_delegating_to_the_client() {
        let contract = contract_for(
            "public type Answer:
    text: String

public agent classify(question: String) -> Answer:
    return Answer(question)

public agent chat(message: String) -> Stream<String>:
    return stream_answer(message)

tool stream_answer(m: String) -> Stream<String>
",
        );
        let api = &files_api(&contract);
        // No server answers a call to a public agent, so the client offers
        // none: a frontend calls the backend through declared actions.
        assert!(!api.contains("classify("), "{api}");
        assert!(!api.contains("chat("), "{api}");
        assert!(!api.contains("/agents"), "{api}");
        // Reuses the shipped transport, never regenerates it.
        assert!(api.contains("import { CorvidClient"));
    }

    /// Every call the generated client makes names a `CorvidClient` method
    /// whose endpoint `corvid serve` answers, so a generated call can never
    /// target a path no server serves.
    #[test]
    fn every_generated_call_reaches_a_served_endpoint() {
        let contract = contract_for(
            "identity users:
    provider google
    provisioning:
        first_login: open
        tenant: fixed(\"public\")

type Note:
    text: String

action save(note: Note) -> Note requires authenticated:
    return note

action watch(topic: String) -> Stream<String> requires authenticated:
    yield topic

public agent helper(x: Int) -> Int:
    return x
",
        );
        let api = files_api(&contract);
        let served = ["action", "actionStream", "routeStream", "subscribe", "login", "session", "logout"];
        let calls: Vec<&str> = api
            .match_indices("this.client.")
            .map(|(at, _)| {
                let rest = &api[at + "this.client.".len()..];
                &rest[..rest.find(|c: char| !c.is_alphanumeric()).unwrap_or(rest.len())]
            })
            .collect();
        assert!(!calls.is_empty());
        for call in calls {
            assert!(served.contains(&call), "the client calls `{call}`, which no served endpoint answers:\n{api}");
        }
        assert!(api.contains("watch(topic: string): RouteStream<string>"), "{api}");
    }

    #[test]
    fn actions_project_to_methods_posting_their_input() {
        let contract = contract_for(
            "type MoveCard:
    card: Int
    position: Int

action move_card(move: MoveCard) -> Int requires anyone:
    return move.position

action rename(card: Int, title: String) -> String requires anyone:
    return title
",
        );
        let api = &files_api(&contract);
        assert!(api.contains("move_card(move: MoveCard): Promise<number>"), "{api}");
        assert!(api.contains("this.client.action<number>(\"move_card\", move)"), "one record is the whole input: {api}");
        assert!(api.contains("rename(card: number, title: string): Promise<string>"), "{api}");
        assert!(api.contains("this.client.action<string>(\"rename\", { card, title })"), "{api}");
        assert!(!api.contains("ApprovalPending"), "no action here can wait for approval: {api}");
    }

    #[test]
    fn identity_projects_login_helpers() {
        let contract = contract_for(
            "identity app_users:
    provider google
    provider github
    provisioning:
        first_login: open
        tenant: fixed(\"public\")

public agent hello(n: String) -> String:
    return n
",
        );
        let api = files_api(&contract);
        assert!(api.contains("loginWith_google()"));
        assert!(api.contains("loginWith_github()"));
        assert!(api.contains("session():"));
        assert!(api.contains("logout():"));
    }

    fn files_api(contract: &ApplicationContract) -> String {
        emit_ts_client(contract)
            .into_iter()
            .find(|f| f.filename == "api.ts")
            .unwrap()
            .contents
    }

    /// A table write's conflict is the union its JSON takes, written as a
    /// declared sum type is.
    #[test]
    fn a_conflict_is_a_union_of_its_cases() {
        assert_eq!(
            ts_type("Result<Member, Conflict<Member>>"),
            "{ tag?: \"ok\"; ok: Member } | { tag?: \"err\"; err: { tag?: \"variant\"; type?: \"Conflict\"; variant: \"Changed\"; fields: [current: Member] } | { tag?: \"variant\"; type?: \"Conflict\"; variant: \"Deleted\" } | { tag?: \"variant\"; type?: \"Conflict\"; variant: \"Taken\"; fields: [holder: Member] } }"
        );
    }
}

#[cfg(test)]
mod protocol_ts_tests {
    use super::*;

    fn contract_for(src: &str) -> ApplicationContract {
        use crate::app_contract::{effect_decls_of, emit_application_contract, ContractOptions};
        use corvid_types::effects::EffectRegistry;
        let tokens = corvid_syntax::lex(src).expect("lex");
        let (file, perr) = corvid_syntax::parse_file(&tokens);
        assert!(perr.is_empty(), "parse: {perr:?}");
        let resolved = corvid_resolve::resolve(&file);
        assert!(resolved.errors.is_empty(), "resolve: {:?}", resolved.errors);
        let registry = EffectRegistry::from_decls(&effect_decls_of(&file));
        let checked = corvid_types::typecheck(&file, &resolved);
        assert!(checked.errors.is_empty(), "check: {:?}", checked.errors);
        emit_application_contract(
            &file,
            &resolved,
            &checked,
            &registry,
            &ContractOptions {
                source_path: "app.cor",
                compiler_version: "test",
                generated_at: "now",
            },
        )
    }

    const SRC: &str = r#"
effect http_write:
    cost: 1.0

type Job:
    id: String
    status: String

connector shipping:
    timeout: 10s
    redirects: never
    published: yes
    base_url: "https://api.example.com"
    auth: bearer(secret("SHIPPING_TOKEN"))
    modes: [real]
    operation submit_shipment(order: String) -> Job dangerous uses http_write:
        POST "/shipments" body order
        async:
            statuses: [queued, processing, completed, failed]
            initial: queued
            terminal: [completed, failed]
            deadline: 600s
            deadline_target: failed
            idempotency: intent via header "Idempotency-Key"
            poll GET "/shipments/{id}"
            every: 30s
            on_protocol_change: refuse
            state queued:
                on queued -> queued
                on processing -> processing
                on completed -> completed
                on failed -> failed
            state processing:
                on queued -> processing
                on processing -> processing
                on completed -> completed
                on failed -> failed

agent main() -> Job uses http_write:
    approve SubmitShipment("order-1")
    return submit_shipment("order-1")
"#;

    /// A long-running operation returns a lifecycle, not a value. The
    /// emitted state union is discriminated on `terminal`, so a client
    /// switch that omits an outcome fails to compile instead of falling
    /// through at runtime.
    #[test]
    fn a_protocol_becomes_a_discriminated_state_union() {
        let types = emit_types(&contract_for(SRC));
        assert!(
            types.contains("export type ShippingSubmitShipmentState ="),
            "the state union must be emitted; got:\n{types}"
        );
        assert!(types.contains(r#"{ state: "processing"; terminal: false }"#));
        assert!(types.contains(r#"{ state: "completed"; terminal: true }"#));
        assert!(
            types.contains(r#"{ state: "failed"; terminal: true }"#),
            "the deadline target must appear as a terminal state"
        );
    }

    /// The status universe is closed: a provider status outside it is
    /// refused at the boundary, so the client type must be a closed union
    /// rather than `string`.
    #[test]
    fn the_status_universe_is_emitted_as_a_closed_union() {
        let types = emit_types(&contract_for(SRC));
        assert!(types.contains("export type ShippingSubmitShipmentStatus ="));
        for status in ["queued", "processing", "completed", "failed"] {
            assert!(
                types.contains(&format!(r#"  | "{status}""#)),
                "status `{status}` must be in the union"
            );
        }
        assert!(
            !types.contains("Status = string"),
            "the status type must never widen to `string`"
        );
    }

    /// Each streaming route is one `Routes` entry keyed by its method and
    /// path, with its arguments in order (path values, query, body) and
    /// the body's encoding; an `Upload` body is named, not generated, and
    /// an ordinary route is not in the table yet.
    #[test]
    fn streaming_routes_become_typed_route_calls() {
        let api = emit_api(&contract_for(
            r#"
type Tick:
    n: Int

type Filter:
    since: Int

agent ticks(n: Int) -> Stream<Tick>:
    yield Tick(n)

traces: none

server app:
    route GET "/boards/{board: Int}/ticks/{lane}" query Filter -> json Stream<Tick>:
        return ticks(path.board)
    route POST "/ticks" body Filter -> json Stream<Tick>:
        return ticks(body.since)
    route POST "/ticks/form" form Filter -> json Stream<Tick>:
        return ticks(body.since)
    @upload(max_bytes: 32, mime: "text/csv")
    route POST "/ticks/upload" body Upload<Csv> -> json Stream<Tick>:
        return ticks(body.size())
    route GET "/count" -> json Int:
        return 1
"#,
        ));
        for expected in [
            r#""GET /boards/{board}/ticks/{lane}": { args: [board: number, lane: string, query: Filter]; reply: RouteStream<Tick> };"#,
            r#""POST /ticks": { args: [body: Filter]; reply: RouteStream<Tick> };"#,
            r#""GET /boards/{board}/ticks/{lane}": { params: ["board", "lane"], query: true, body: null },"#,
            r#""POST /ticks": { params: [], query: false, body: "json" },"#,
            r#""POST /ticks/form": { params: [], query: false, body: "form" },"#,
            r#"// Not generated yet: "POST /ticks/upload" streams over an `Upload` body"#,
            r#"route<K extends keyof Routes>(route: K, ...args: Routes[K]["args"]): Routes[K]["reply"]"#,
        ] {
            assert!(api.contains(expected), "missing `{expected}` in:\n{api}");
        }
        assert!(!api.contains("/count"), "ordinary routes are not generated yet:\n{api}");
        assert!(!api.contains(r#""POST /ticks/upload": {"#), "{api}");
    }

    /// An app without a streaming route gets no `Routes` table and no
    /// route method.
    #[test]
    fn an_app_without_stream_routes_has_no_route_method() {
        let api = emit_api(&contract_for(SRC));
        assert!(!api.contains("interface Routes") && !api.contains("routeStream"), "{api}");
    }

    /// A protocol on a `published: no` connector is backend only, so the
    /// generated client carries none of its types: a frontend that
    /// imports them stops compiling, and the choice shows in both tiers.
    #[test]
    fn an_unpublished_connector_generates_no_protocol_types() {
        let types = emit_types(&contract_for(&SRC.replace("published: yes", "published: no")));
        assert!(
            !types.contains("ShippingSubmitShipment"),
            "an unpublished protocol must not reach the client; got:\n{types}"
        );
    }

    /// The client is generated against a specific protocol graph. Shipping
    /// the fingerprint lets it detect that the backend is now running a
    /// different one.
    #[test]
    fn the_generated_client_carries_the_protocol_fingerprint() {
        let types = emit_types(&contract_for(SRC));
        assert!(types.contains("export const ShippingSubmitShipmentProtocol"));
        assert!(
            types.contains("fingerprint: \"sha256:"),
            "the fingerprint must be emitted so a client can detect drift"
        );
        assert!(types.contains("deadlineTarget: \"failed\""));
        assert!(types.contains("onProtocolChange: \"refuse\""));
    }

    /// No protocols, no protocol types — the generator must not emit
    /// scaffolding for a surface the program does not have.
    #[test]
    fn a_contract_without_protocols_emits_no_protocol_types() {
        let types = emit_types(&contract_for("agent main() -> String:\n    return \"hi\"\n"));
        assert!(!types.contains("Protocol = {"));
        assert!(!types.contains("State ="));
    }
}
